let data,map,flightTime=0,paused=false,speed=1,lastFrame=0,lastDraw=0,lastTouch=performance.now(),visibleControls=true,hits=[],pending=null,selectedAircraft=null,selectedAirport=null,airportRunway=0,airportDataPage=false,frameState=[],mapStamp=-Infinity,mapKey='',mapOrigin=null;
