function syncControls(){controls.classList.toggle('hidden',!visibleControls||!!selectedAirport);$('mapButton').textContent=['Map · Off','Map · Low','Map · Normal'][settings.map];$('airportButton').textContent='Airports · '+(settings.airports?'On':'Off');document.querySelectorAll('[data-range]').forEach(b=>{b.classList.toggle('active',+b.dataset.range===settings.range);b.setAttribute('aria-pressed',String(+b.dataset.range===settings.range));});}
function dialog(id){$(id).showModal();}
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());
for(const id of ['setupDialog','aircraftDialog','guideDialog','notesDialog'])$(id).addEventListener('click',e=>{if(e.target===$(id)){const r=$(id).getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$(id).close();}});
$('aircraftDialog').addEventListener('close',()=>selectedAircraft=null);
function populateForm(values){for(const [key,value] of Object.entries(values)){const field=$('setupForm').elements.namedItem(key);if(field){if(field.type==='checkbox')field.checked=value;else field.value=String(value);}}}
$('setupButton').onclick=()=>{wake();populateForm(settings);dialog('setupDialog');};
$('defaultsButton').onclick=()=>populateForm(DEFAULTS);
$('setupForm').onsubmit=e=>{e.preventDefault();const values={};for(const key of Object.keys(DEFAULTS)){const field=e.currentTarget.elements.namedItem(key);values[key]=field.type==='checkbox'?field.checked:field.value;}settings=validateSettings(values);save();mapKey='';$('setupDialog').close();wake();};
$('mapButton').onclick=()=>{settings.map=(settings.map+1)%3;save();mapKey='';wake();};$('airportButton').onclick=()=>{settings.airports=!settings.airports;save();wake();};
