$('exportNotes').onclick=()=>{const text=`FishFinder iPad demo ${VERSION}\n${new Date().toISOString()}\nSimulation: ${Math.floor(flightTime)} s; speed ${speed}×\nSettings: ${JSON.stringify(settings)}\n\n${$('notes').value}\n`,url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='FishFinder-test-notes.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
function logical(e){const r=canvas.getBoundingClientRect();return [(e.clientX-r.left)*800/r.width,(e.clientY-r.top)*800/r.height];}
canvas.addEventListener('pointerup',e=>{if(!data||selectedAirport)return;const [x,y]=logical(e),now=performance.now();if(pending){clearTimeout(pending.timer);const old=pending;pending=null;if(now-old.time<=300&&Math.hypot(x-old.x,y-old.y)<=32){wake();return;}}const captured=hits.slice();pending={x,y,time:now,timer:setTimeout(()=>{pending=null;const candidates=captured.filter(h=>Math.hypot(h.x-x,h.y-y)<=28);const hit=candidates.find(h=>h.type==='ownship')||candidates.filter(h=>h.type==='aircraft').sort((a,b)=>Math.hypot(a.x-x,a.y-y)-Math.hypot(b.x-x,b.y-y))[0]||candidates.sort((a,b)=>Math.hypot(a.x-x,a.y-y)-Math.hypot(b.x-x,b.y-y))[0];if(hit){if(visibleControls)lastTouch=performance.now();if(hit.type==='ownship')openAircraft('__ownship__');else if(hit.type==='aircraft')openAircraft(hit.id);else openAirport(hit.airport);}else if(visibleControls)lastTouch=performance.now();},300)};});
canvas.addEventListener('dblclick',e=>e.preventDefault());
function text(x,y,value,size=12,color='#d9ece1',align='center'){ctx.fillStyle=color;ctx.font=`${size}px -apple-system,BlinkMacSystemFont,sans-serif`;ctx.textAlign=align;ctx.textBaseline='middle';ctx.fillText(value,x,y);}
function line(points,color,width=1,dash=[]){if(points.length<2)return;ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.strokeStyle=color;ctx.lineWidth=width;ctx.setLineDash(dash);ctx.stroke();ctx.setLineDash([]);}
