function makePath(points){const p=new Path2D();points.forEach(([lat,lon],i)=>{const [x,y]=localPoint(lat,lon);i?p.lineTo(x,y):p.moveTo(x,y);});return p;}
function prepareMap(){paths=map.paths.map(p=>({kind:p.kind,path:makePath(p.points)}));polygons=map.water_polygons.map(rings=>{const p=new Path2D();for(const ring of rings){p.addPath(makePath(ring));p.closePath();}return p;});}
